package mz.gov.mogovolas.expedientes.service;
import mz.gov.mogovolas.expedientes.entity.*; import mz.gov.mogovolas.expedientes.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service public class ExpedienteService {final ExpedienteRepository repo;final UtilizadorRepository users;final SectorRepository sectors;final TramitacaoRepository tram;final DespachoRepository desp; public ExpedienteService(ExpedienteRepository r,UtilizadorRepository u,SectorRepository s,TramitacaoRepository t,DespachoRepository d){repo=r;users=u;sectors=s;tram=t;desp=d;} @Transactional public Expediente criar(Expediente e,String user){Utilizador u=users.findByUsername(user).orElseThrow();e.setNumero("EXP-"+Year.now().getValue()+"-"+String.format("%05d",repo.count()+1));e.setDataEntrada(LocalDateTime.now());e.setCriadoPor(u);e.setSectorActual(u.getSector());e.setEstado(Expediente.EstadoExpediente.REGISTADO);return repo.save(e);} public List<Expediente> listar(String q){return q==null||q.isBlank()?repo.findAll(org.springframework.data.domain.Sort.by(org.springframework.data.domain.Sort.Direction.DESC,"dataEntrada")):repo.pesquisar(q);} public Expediente obter(Long id){return repo.findById(id).orElseThrow(()->new IllegalArgumentException("Expediente não encontrado"));} @Transactional public void receber(Long id,String user){Tramitacao t=tram.findTopByExpedienteIdOrderByDataEnvioDesc(id).orElseThrow();Utilizador u=users.findByUsername(user).orElseThrow();t.setRecebidoPor(u);t.setDataRecepcao(LocalDateTime.now());t.setEstado(Tramitacao.EstadoTramitacao.RECEBIDO);Expediente e=obter(id);e.setSectorActual(t.getSectorDestino());e.setEstado(Expediente.EstadoExpediente.RECEBIDO);repo.save(e);tram.save(t);} @Transactional public void tramitar(Long id,Long destino,String obs,String user){Expediente e=obter(id);Utilizador u=users.findByUsername(user).orElseThrow();Sector s=sectors.findById(destino).orElseThrow();Tramitacao t=new Tramitacao();t.setExpediente(e);t.setSectorOrigem(e.getSectorActual());t.setSectorDestino(s);t.setEnviadoPor(u);t.setDataEnvio(LocalDateTime.now());t.setObservacao(obs);t.setEstado(Tramitacao.EstadoTramitacao.ENVIADO);tram.save(t);e.setEstado(Expediente.EstadoExpediente.EM_TRAMITACAO);repo.save(e);} @Transactional public void despacho(Long id,String texto,String user){Expediente e=obter(id);Utilizador u=users.findByUsername(user).orElseThrow();Despacho d=new Despacho();d.setExpediente(e);d.setUtilizador(u);d.setTexto(texto);d.setDataDespacho(LocalDateTime.now());desp.save(d);e.setEstado(Expediente.EstadoExpediente.DESPACHADO);repo.save(e);} @Transactional public void arquivar(Long id){Expediente e=obter(id);e.setEstado(Expediente.EstadoExpediente.ARQUIVADO);repo.save(e);} public Map<String,Long> indicadores(){Map<String,Long>m=new LinkedHashMap<>();m.put("total",repo.count());m.put("emTramitacao",repo.countByEstado(Expediente.EstadoExpediente.EM_TRAMITACAO));m.put("recebidos",repo.countByEstado(Expediente.EstadoExpediente.RECEBIDO));m.put("arquivados",repo.countByEstado(Expediente.EstadoExpediente.ARQUIVADO));m.put("urgentes",repo.countByPrioridade(Expediente.Prioridade.URGENTE)+repo.countByPrioridade(Expediente.Prioridade.MUITO_URGENTE));return m;}}
